      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        background:
          radial-gradient(circle at top, #eef4ff 0, #f3f5fb 32%, #edf1f8 100%);
        color: var(--text);
