      a,
      button {
        font: inherit;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        transform: translateY(-220%);
        padding: 0.75rem 1rem;
        border-radius: 999px;
        background: var(--text);
        color: #fff;
        text-decoration: none;
        z-index: 20;
      }

      .skip-link:focus-visible {
        transform: translateY(0);
      }

      .page {
        width: min(100%, 72rem);
        margin: 0 auto;
        padding: 2rem 1rem 3rem;
      }

      .hero {
        display: grid;
        gap: 1rem;
        margin-bottom: 2rem;
      }

      .eyebrow {
        margin: 0;
        color: var(--accent-strong);
        font-weight: 700;
        letter-spacing: 0.04em;
        text-transform: uppercase;
        font-size: 0.8rem;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 5vw, 3.5rem);
        line-height: 1.05;
      }

      .hero p {
        margin: 0;
        max-width: 40rem;
        color: var(--text-muted);
        font-size: 1.05rem;
        line-height: 1.6;
      }

      .preview-layout {
        display: grid;
        grid-template-columns: minmax(0, 1.4fr) minmax(18rem, 0.9fr);
        gap: 1.5rem;
      }

      .card,
      .details {
        background: rgba(255, 255, 255, 0.86);
        backdrop-filter: blur(10px);
        border: 1px solid rgba(216, 222, 234, 0.85);
        border-radius: var(--radius-xl);
        box-shadow: var(--shadow);
      }

      .card {
        padding: 1.1rem;
      }

      .image-frame {
        overflow: hidden;
        border-radius: calc(var(--radius-xl) - 8px);
        border: 1px solid var(--border);
        background: #dbe5ff;
        aspect-ratio: 16 / 10;
      }

      .image-frame img {
        display: block;
        width: 100%;
        height: 100%;
        object-fit: cover;
      }

      .image-footer {
        display: flex;
        gap: 1rem;
        justify-content: space-between;
        align-items: center;
        padding: 1.1rem 0 0.2rem;
      }

      .image-meta h2 {
        margin: 0 0 0.35rem;
        font-size: 1.2rem;
      }

      .image-meta p {
        margin: 0;
        color: var(--text-muted);
      }

      .button-row {
        display: flex;
        gap: 0.75rem;
        flex-wrap: wrap;
        justify-content: flex-end;
      }

      button {
        border: 0;
        border-radius: 999px;
        padding: 0.9rem 1.2rem;
        cursor: pointer;
        transition:
          transform 160ms ease,
          background-color 160ms ease,
          color 160ms ease,
          box-shadow 160ms ease;
      }

      button:hover {
        transform: translateY(-1px);
      }

      button:focus-visible,
      .skip-link:focus-visible {
        outline: 3px solid transparent;
        box-shadow:
          0 0 0 3px #fff,
          0 0 0 5px var(--accent);
      }

      .secondary-button {
        background: var(--surface-muted);
        color: var(--text);
      }

      .secondary-button:hover {
        background: #eef1f8;
      }

      .danger-button {
        background: var(--danger);
        color: #fff;
        box-shadow: 0 10px 20px rgba(217, 45, 32, 0.18);
      }

      .danger-button:hover {
        background: var(--danger-strong);
      }

      .details {
        padding: 1.5rem;
        align-self: start;
      }

      .details h2 {
        margin: 0 0 1rem;
        font-size: 1.1rem;
      }

      .detail-list {
        display: grid;
        gap: 0.9rem;
      }

      .detail-item {
        padding: 1rem;
        border-radius: var(--radius-md);
        background: var(--surface-muted);
      }

      .detail-item span {
        display: block;
        margin-bottom: 0.35rem;
        color: var(--text-muted);
        font-size: 0.92rem;
      }

      .detail-item strong {
        display: block;
        font-size: 1rem;
        overflow-wrap: anywhere;
      }

      .status {
        margin-top: 1rem;
        min-height: 1.5rem;
        color: #0f766e;
        font-weight: 600;
      }

      dialog {
        width: min(100% - 2rem, 30rem);
        padding: 0;
        border: 0;
        border-radius: 1.5rem;
        box-shadow: 0 24px 60px rgba(15, 23, 42, 0.28);
      }

      dialog::backdrop {
        background: rgba(15, 23, 42, 0.55);
        backdrop-filter: blur(5px);
      }

      .dialog-content {
        padding: 1.5rem;
      }

      .dialog-icon {
        display: inline-grid;
        place-items: center;
        width: 3rem;
        height: 3rem;
        border-radius: 999px;
        background: #fee4e2;
        color: var(--danger);
        font-size: 1.4rem;
        font-weight: 700;
      }

      .dialog-content h2 {
        margin: 1rem 0 0.6rem;
        font-size: 1.4rem;
      }

      .dialog-content p {
        margin: 0;
        color: var(--text-muted);
        line-height: 1.6;
      }

      .dialog-actions {
        display: flex;
        justify-content: flex-end;
        gap: 0.75rem;
        flex-wrap: wrap;
        margin-top: 1.5rem;
      }

      button:disabled {
        cursor: not-allowed;
        opacity: 1;
        transform: none;
        background: #e5e7eb;
        color: #6b7280;
        box-shadow: none;
      }

      @media (max-width: 48rem) {
        .preview-layout {
          grid-template-columns: 1fr;
        }

        .image-footer {
          align-items: flex-start;
          flex-direction: column;
        }

        .button-row,
        .dialog-actions {
          width: 100%;
        }

        .button-row button,
        .dialog-actions button {
          flex: 1 1 12rem;
        }
