        .secondary-button,
        .danger-button {
          background: Canvas;
          color: CanvasText;
          border: 1px solid ButtonText;
          box-shadow: none;
        }

        .dialog-icon {
          background: Canvas;
          color: CanvasText;
          border: 1px solid ButtonText;
        }

        .status,
        .eyebrow,
        .hero p,
        .image-meta p,
        .detail-item span,
        .dialog-content p {
          color: CanvasText;
        }
      }
    </style>
  </head>
