    <script>
      const openDialogButton = document.getElementById("open-dialog");
      const cancelDialogButton = document.getElementById("cancel-dialog");
      const confirmDeleteButton = document.getElementById("confirm-delete");
      const deleteDialog = document.getElementById("delete-dialog");
      const imageTitle = document.getElementById("image-title");
      const previewImage = document.getElementById("preview-image");
      const statusMessage = document.getElementById("status-message");
      let lastFocusedElement = null;

      function closeDialog() {
        deleteDialog.close();
      }

      openDialogButton.addEventListener("click", () => {
        lastFocusedElement = document.activeElement;
        deleteDialog.showModal();
        cancelDialogButton.focus();
      });

      cancelDialogButton.addEventListener("click", closeDialog);

      deleteDialog.addEventListener("cancel", () => {
        if (lastFocusedElement instanceof HTMLElement) {
          lastFocusedElement.focus();
        }
      });

      deleteDialog.addEventListener("close", () => {
        if (deleteDialog.returnValue !== "deleted" && lastFocusedElement instanceof HTMLElement) {
          lastFocusedElement.focus();
        }
      });

      deleteDialog.addEventListener("click", (event) => {
        const dialogBounds = deleteDialog.getBoundingClientRect();
        const isInDialog =
          dialogBounds.top <= event.clientY &&
          event.clientY <= dialogBounds.top + dialogBounds.height &&
          dialogBounds.left <= event.clientX &&
          event.clientX <= dialogBounds.left + dialogBounds.width;

        if (!isInDialog) {
          closeDialog();
        }
      });

      confirmDeleteButton.addEventListener("click", () => {
        imageTitle.textContent = "Image deleted";
        previewImage.style.opacity = "0.35";
        previewImage.alt = "Deleted image preview placeholder";
        openDialogButton.disabled = true;
        openDialogButton.textContent = "Deleted";
        statusMessage.textContent = "Aurora Peaks was removed from your library.";
        deleteDialog.close("deleted");
      });
    </script>
