        top: 1rem;
        transform: translateY(-220%);
        padding: 0.75rem 1rem;
        border-radius: 999px;
        background: var(--text);
        color: #fff;
        text-decoration: none;
        z-index: 20;
      }

      .skip-link:focus-visible {
        transform: translateY(0);
      }

      .page {
        width: min(100%, 72rem);
        margin: 0 auto;
        padding: 2rem 1rem 3rem;
