        border-radius: var(--radius-md);
        background: var(--surface-muted);
      }

      .detail-item span {
        display: block;
        margin-bottom: 0.35rem;
        color: var(--text-muted);
        font-size: 0.92rem;
      }

      .detail-item strong {
        display: block;
        font-size: 1rem;
        overflow-wrap: anywhere;
      }

      .status {
        margin-top: 1rem;
        min-height: 1.5rem;
        color: #0f766e;
        font-weight: 600;
      }

      dialog {
        width: min(100% - 2rem, 30rem);
        padding: 0;
        border: 0;
        border-radius: 1.5rem;
        box-shadow: 0 24px 60px rgba(15, 23, 42, 0.28);
      }

      dialog::backdrop {
        background: rgba(15, 23, 42, 0.55);
        backdrop-filter: blur(5px);
      }

      .dialog-content {
        padding: 1.5rem;
      }

      .dialog-icon {
        display: inline-grid;
        place-items: center;
        width: 3rem;
        height: 3rem;
        border-radius: 999px;
        background: #fee4e2;
        color: var(--danger);
        font-size: 1.4rem;
        font-weight: 700;
      }

      .dialog-content h2 {
        margin: 1rem 0 0.6rem;
        font-size: 1.4rem;
      }

      .dialog-content p {
        margin: 0;
        color: var(--text-muted);
        line-height: 1.6;
      }

      .dialog-actions {
        display: flex;
        justify-content: flex-end;
        gap: 0.75rem;
        flex-wrap: wrap;
        margin-top: 1.5rem;
      }

      button:disabled {
        cursor: not-allowed;
        opacity: 1;
        transform: none;
        background: #e5e7eb;
        color: #6b7280;
        box-shadow: none;
      }

      @media (max-width: 48rem) {
        .preview-layout {
          grid-template-columns: 1fr;
        }

        .image-footer {
          align-items: flex-start;
          flex-direction: column;
        }

        .button-row,
        .dialog-actions {
          width: 100%;
        }

        .button-row button,
        .dialog-actions button {
          flex: 1 1 12rem;
